$(function() {
	const backToTopButton = $('<button>', {
		class: 'btn btn-dark position-fixed bottom-0 end-0 m-3 rounded-circle shadow',
		type: 'button',
		'aria-label': 'Back to top',
		title: 'Back to top',
		html: '<i class="fa-solid fa-arrow-up" aria-hidden="true"></i>'
	}).css({
		display: 'none',
		zIndex: 1030,
		width: '2.75rem',
		height: '2.75rem',
		padding: 0
	}).appendTo('body');

	$(window).on('scroll', function() {
		if ($(window).scrollTop() > 400) {
			backToTopButton.stop(true, true).fadeIn(180);
		} else {
			backToTopButton.stop(true, true).fadeOut(180);
		}
	});

	backToTopButton.on('click', function() {
		$('html, body').stop(true).animate({ scrollTop: 0 }, 400);
	});
});